package thaumcraft.entities;

import net.minecraft.core.registries.Registries;
import net.minecraft.world.entity.*;
import net.neoforged.bus.api.IEventBus;
import net.neoforged.neoforge.registries.*;

public final class R5Entities {
    private static final DeferredRegister<EntityType<?>> TYPES=DeferredRegister.create(Registries.ENTITY_TYPE,"thaumcraft");
    public static final DeferredHolder<EntityType<?>,EntityType<GrateItem>> GRATE_ITEM=TYPES.register("grate_item",()->EntityType.Builder.<GrateItem>of(GrateItem::new,MobCategory.MISC).sized(.25f,.25f).clientTrackingRange(4).updateInterval(20).build("thaumcraft:grate_item"));
    public static final DeferredHolder<EntityType<?>,EntityType<FollowingItem>> FOLLOWING_ITEM=TYPES.register("following_item",()->EntityType.Builder.<FollowingItem>of(FollowingItem::new,MobCategory.MISC).sized(.25f,.25f).setShouldReceiveVelocityUpdates(false).clientTrackingRange(4).updateInterval(20).build("thaumcraft:following_item"));
    public static final DeferredHolder<EntityType<?>,EntityType<EldritchCrab>> CRAB=TYPES.register("eldritch_crab",()->EntityType.Builder.<EldritchCrab>of(EldritchCrab::new,MobCategory.MONSTER).sized(.8f,.6f).clientTrackingRange(8).build("thaumcraft:eldritch_crab"));
    public static final DeferredHolder<EntityType<?>,EntityType<InhabitedZombie>> INHABITED_ZOMBIE=TYPES.register("inhabited_zombie",()->EntityType.Builder.<InhabitedZombie>of(InhabitedZombie::new,MobCategory.MONSTER).sized(.6f,1.8f).build("thaumcraft:inhabited_zombie"));
    public static final DeferredHolder<EntityType<?>,EntityType<PermanentItemEntity>> PERMANENT_ITEM=TYPES.register("permanent_item",()->EntityType.Builder.<PermanentItemEntity>of(PermanentItemEntity::new,MobCategory.MISC).sized(.25f,.25f).clientTrackingRange(6).updateInterval(20).build("thaumcraft:permanent_item"));
    public static final DeferredHolder<EntityType<?>,EntityType<EldritchGolem>> ELDRITCH_GOLEM=TYPES.register("eldritch_golem",()->EntityType.Builder.<EldritchGolem>of(EldritchGolem::new,MobCategory.MONSTER).sized(1.75f,3.5f).eyeHeight(3).fireImmune().clientTrackingRange(4).updateInterval(3).build("thaumcraft:eldritch_golem"));
    public static final DeferredHolder<EntityType<?>,EntityType<GolemOrb>> GOLEM_ORB=TYPES.register("golem_orb",()->EntityType.Builder.<GolemOrb>of(GolemOrb::new,MobCategory.MISC).sized(.25f,.25f).clientTrackingRange(4).updateInterval(20).build("thaumcraft:golem_orb"));
    public static final DeferredHolder<EntityType<?>,EntityType<SpecialItemEntity>> SPECIAL_ITEM=TYPES.register("special_item",()->EntityType.Builder.<SpecialItemEntity>of(SpecialItemEntity::new,MobCategory.MISC).sized(.25f,.25f).clientTrackingRange(4).updateInterval(20).build("thaumcraft:special_item"));
    public static final DeferredHolder<EntityType<?>,EntityType<EldritchWarden>> ELDRITCH_WARDEN=TYPES.register("eldritch_warden",()->EntityType.Builder.<EldritchWarden>of(EldritchWarden::new,MobCategory.MONSTER).sized(1.5f,3.5f).eyeHeight(3.1f).clientTrackingRange(4).updateInterval(3).build("thaumcraft:eldritch_warden"));
    public static final DeferredHolder<EntityType<?>,EntityType<CultistLeader>> CULTIST_LEADER=TYPES.register("cultist_leader",()->EntityType.Builder.<CultistLeader>of(CultistLeader::new,MobCategory.MONSTER).sized(.75f,2.25f).clientTrackingRange(4).updateInterval(3).build("thaumcraft:cultist_leader"));
    public static final DeferredHolder<EntityType<?>,EntityType<CultistPortal>> CULTIST_PORTAL=TYPES.register("cultist_portal",()->EntityType.Builder.<CultistPortal>of(CultistPortal::new,MobCategory.MONSTER).sized(1.5f,3).fireImmune().clientTrackingRange(4).updateInterval(3).build("thaumcraft:cultist_portal"));
    public static final DeferredHolder<EntityType<?>,EntityType<TaintacleGiant>> TAINTACLE_GIANT=TYPES.register("taintacle_giant",()->EntityType.Builder.<TaintacleGiant>of(TaintacleGiant::new,MobCategory.MONSTER).sized(1.1f,6).clientTrackingRange(4).updateInterval(3).build("thaumcraft:taintacle_giant"));
    public static final DeferredHolder<EntityType<?>,EntityType<CultistKnight>> CULTIST_KNIGHT=TYPES.register("cultist_knight",()->EntityType.Builder.<CultistKnight>of(CultistKnight::new,MobCategory.MONSTER).sized(.6f,1.8f).clientTrackingRange(4).updateInterval(3).build("thaumcraft:cultist_knight"));
    public static final DeferredHolder<EntityType<?>,EntityType<CultistCleric>> CULTIST_CLERIC=TYPES.register("cultist_cleric",()->EntityType.Builder.<CultistCleric>of(CultistCleric::new,MobCategory.MONSTER).sized(.6f,1.8f).clientTrackingRange(4).updateInterval(3).build("thaumcraft:cultist_cleric"));
    public static final DeferredHolder<EntityType<?>,EntityType<Pech>> PECH=TYPES.register("pech",()->EntityType.Builder.<Pech>of(Pech::new,MobCategory.MONSTER).sized(.6f,1.8f).eyeHeight(1.8f*.66f).clientTrackingRange(8).updateInterval(3).build("thaumcraft:pech"));
    public static final DeferredHolder<EntityType<?>,EntityType<PechBlast>> PECH_BLAST=TYPES.register("pech_blast",()->EntityType.Builder.<PechBlast>of(PechBlast::new,MobCategory.MISC).sized(.25f,.25f).clientTrackingRange(4).updateInterval(20).build("thaumcraft:pech_blast"));
    public static void register(IEventBus bus){TYPES.register(bus);bus.addListener((net.neoforged.neoforge.event.entity.EntityAttributeCreationEvent event)->{event.put(CRAB.get(),EldritchCrab.attributes().build());event.put(INHABITED_ZOMBIE.get(),InhabitedZombie.attributes().build());event.put(ELDRITCH_GOLEM.get(),EldritchGolem.attributes().build());event.put(ELDRITCH_WARDEN.get(),EldritchWarden.attributes().build());event.put(CULTIST_LEADER.get(),CultistLeader.attributes().build());event.put(CULTIST_PORTAL.get(),CultistPortal.attributes().build());event.put(TAINTACLE_GIANT.get(),TaintacleGiant.attributes().build());event.put(CULTIST_KNIGHT.get(),CultistKnight.attributes().build());event.put(CULTIST_CLERIC.get(),CultistCleric.attributes().build());event.put(PECH.get(),Pech.attributes().build());});}
    private R5Entities(){}
}
